import sys
from datetime import datetime, timedelta


def minutes(text):
    h, m = text.split(":")
    return int(h) * 60 + int(m)


def hm(total):
    return f"{total // 60}:{total % 60:02d}"


def parse_shift(start_str, end_str):
    start = datetime.strptime(start_str, "%H:%M")
    end = datetime.strptime(end_str, "%H:%M")
    if end < start:
        end += timedelta(days=1)
    return end - start


def main():
    target = {}
    weeks = {}
    for line in sys.stdin:
        parts = line.strip().split()
        if not parts:
            continue
        if parts[0] == "target":
            target[parts[1]] = minutes(parts[2])
            continue
        name, day, start, end = parts
        week = datetime.strptime(day, "%Y-%m-%d").strftime("%Y-W%W")
        shift_duration = parse_shift(start, end)
        key = (name, week)
        weeks[key] = weeks.get(key, 0) + shift_duration.seconds // 3600 * 60 + shift_duration.seconds % 3600
    balance = {}
    for name, week in sorted(weeks):
        target_hours = target.get(name, 40 * 60)
        worked_hours = weeks[(name, week)]
        diff = worked_hours - target_hours
        balance[name] = balance.get(name, 0) + diff
        sign = "+" if diff >= 0 else "-"
        print(f"{name} {week} {hm(worked_hours)} {sign}{hm(abs(diff))}")
    for name in sorted(balance):
        print(f"{name} overtime {hm(max(balance[name], 0))}")


if __name__ == "__main__":
    main()
